package edu.seu.vcampus.common.course; import java.io.*; import java.time.*; import java.util.Objects;
/** Optimistically updates a complete term configuration. */ public record UpdateTermCommand(String termId,String termCode,String termName,LocalDate startDate,LocalDate endDate,Instant enrollmentStartAt,Instant enrollmentEndAt,Instant adjustmentStartAt,Instant adjustmentEndAt,String termStatus,long expectedVersion)implements Serializable{@Serial private static final long serialVersionUID=1L;public UpdateTermCommand{Objects.requireNonNull(termId);new CreateTermCommand(termCode,termName,startDate,endDate,enrollmentStartAt,enrollmentEndAt,adjustmentStartAt,adjustmentEndAt,termStatus);CourseValidation.text("termId",termId,36);if(expectedVersion<0)throw new IllegalArgumentException("invalid term");}}
